(7057575, 1073835, 23484, '<td valign="top">St Louis is such a cool city. Great job on the night skyline.  I went up in the arch one time, quite a ride.</td>', 'St Louis is such a cool city. Great job on the night skyline.  I went up in the arch one time, quite a ride.', '2013-06-29 15:40:07.000000', NULL, 1),
(7057576, 1073532, 23484, '<td valign="top">The high key look is great.</td>', 'The high key look is great.', '2013-06-29 15:40:23.000000', NULL, 1),
