(7059232, 1073664, 72103, '<td valign="top">Potential for a great photo here, but IMHO over-processed (although I''m one to talk!!! )...</td>', 'Potential for a great photo here, but IMHO over-processed (although I''m one to talk!!! )...', '2013-07-02 11:01:11.000000', NULL, 1),
