(7059237, 1073655, 72103, '<td valign="top">Too tightly cropped IMHO - 5</td>', 'Too tightly cropped IMHO - 5', '2013-07-02 11:04:28.000000', NULL, 1),
(7059240, 1073856, 72103, '<td valign="top">IMHO i would have cropped closer to the kid, had him further down and more to the edge.  I think you''ll find teh feeling of isolation would have been greater, smaller in a large world.........    :)</td>', 'IMHO i would have cropped closer to the kid, had him further down and more to the edge.  I think you''ll find teh feeling of isolation would have been greater, smaller in a large world.........    :)', '2013-07-02 11:06:52.000000', NULL, 1),
