(7060084, 1073828, 28427, '<td valign="top">Hope he found his dinner, like you found this little gem</td>', 'Hope he found his dinner, like you found this little gem', '2013-07-03 08:22:11.000000', NULL, 1),
(7060085, 1073693, 28427, '<td valign="top">He was moving towards you?? I admire your guts!</td>', 'He was moving towards you?? I admire your guts!', '2013-07-03 08:24:07.000000', NULL, 1),
(7060086, 1073744, 28427, '<td valign="top">Very colourful.  This would make a great poster</td>', 'Very colourful.  This would make a great poster', '2013-07-03 08:25:14.000000', NULL, 1),
(7060087, 1073698, 28427, '<td valign="top">How peaceful.  You''ve taken the right decision I think to set this in monochrome</td>', 'How peaceful.  You''ve taken the right decision I think to set this in monochrome', '2013-07-03 08:26:06.000000', NULL, 1),
