(7060843, 1073784, 97225, '<td valign="top">Wonderful shot!</td>', 'Wonderful shot!', '2013-07-04 22:08:20.000000', NULL, 1),
(7060856, 1073073, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Love the colors of the clouds, the glow of the moon and the strike of lightning. It is the golds, soft oranges and the steely blues that color the heavens with an ethereal air. Given the light soft hues of the heavens above I think that this would be more visually stunning if you cropped out all of or nearly all of the heavy dark tones of the ground plain. It weighs down the light and airy feel seen in the ethereal clouds.</td>', 'Voted earlier coming back to comment. Love the colors of the clouds, the glow of the moon and the strike of lightning. It is the golds, soft oranges and the steely blues that color the heavens with an ethereal air. Given the light soft hues of the heavens above I think that this would be more visually stunning if you cropped out all of or nearly all of the heavy dark tones of the ground plain. It weighs down the light and airy feel seen in the ethereal clouds.', '2013-07-04 23:11:39.000000', NULL, 1),
(7060870, 1073393, 114285, '<td valign="top">Is this the sea of Galilee, WOW, the vignetting is a bit to excessive, I''ve been guilty of that too. 7</td>', 'Is this the sea of Galilee, WOW, the vignetting is a bit to excessive, I''ve been guilty of that too. 7', '2013-07-05 00:15:11.000000', NULL, 1),
